fn is_integer(text: &Vec<char>) -> bool {
    // An empty vector should return true
    // We check every character to see if it falls in the ASCII range '0'..='9'
    for &c in text.iter() {
        if c < '0' || c > '9' {
            return false;
        }
    }
    true
}

